<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
function upload_tour_image(string $field,int $tourId,string $kind): string {
 if(empty($_FILES[$field]) || (int)$_FILES[$field]['error']===UPLOAD_ERR_NO_FILE) return '';
 $f=$_FILES[$field]; if((int)$f['error']!==UPLOAD_ERR_OK) throw new RuntimeException('Could not upload the '.$kind.' image.');
 if((int)$f['size']>5*1024*1024) throw new RuntimeException('The '.$kind.' image must be 5 MB or smaller.');
 $info=@getimagesize((string)$f['tmp_name']); if(!$info) throw new RuntimeException('The '.$kind.' file is not a valid image.');
 $mime=(string)($info['mime']??''); $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp']; if(!isset($allowed[$mime])) throw new RuntimeException('The '.$kind.' must be JPG, PNG or WebP.');
 $minW=$kind==='cover'?1200:200; $minH=$kind==='cover'?450:60; if((int)$info[0]<$minW||(int)$info[1]<$minH) throw new RuntimeException(ucfirst($kind).' image must be at least '.$minW.' × '.$minH.' px.');
 $dir=__DIR__.'/uploads/tours/'.$tourId; if(!is_dir($dir)&&!mkdir($dir,0755,true)&&!is_dir($dir)) throw new RuntimeException('Could not create the image upload directory.');
 $name=$kind.'-'.bin2hex(random_bytes(8)).'.'.$allowed[$mime]; if(!move_uploaded_file((string)$f['tmp_name'],$dir.'/'.$name)) throw new RuntimeException('Could not save the '.$kind.' image.');
 return 'uploads/tours/'.$tourId.'/'.$name;
}
saas_require_login();
$orgId=saas_require_organization();saas_require_permission('tour.edit');$id=(int)($_GET['id']??$_POST['id']??0);$db=saas_db();if($id<=0)$id=saas_current_tour_id();
$q=$db->prepare("SELECT t.* FROM tours t INNER JOIN tour_members tm ON tm.tour_id=t.id WHERE t.id=? AND t.organization_id=? AND tm.user_id=? AND tm.status='ACTIVE' LIMIT 1");$q->execute([$id,$orgId,saas_user_id()]);$t=$q->fetch();if(!$t){http_response_code(404);exit('Tour not found.');}
$q=$db->prepare("SELECT setting_key,setting_value FROM tour_settings WHERE tour_id=? AND setting_key IN ('default_transport','banner_image','logo_image','departure_options')");$q->execute([$id]);$settings=[];foreach($q as $s)$settings[$s['setting_key']]=$s['setting_value'];
$error='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{saas_check_csrf();$name=trim((string)$_POST['name']);$start=trim((string)$_POST['start_date']);$end=trim((string)$_POST['end_date']);$fee=max(0,(float)$_POST['default_fee']);$desc=trim((string)$_POST['description']);$status=strtoupper(trim((string)$_POST['status']));$transport=strtoupper(trim((string)$_POST['default_transport']));$banner=trim((string)$_POST['banner_image']);$logo=trim((string)($_POST['logo_image']??''));$departures=array_values(array_filter(array_map('trim',preg_split('/\R+/',(string)($_POST['departure_options']??'')))));if($name==='')throw new RuntimeException('Tour name is required.');if($end!==''&&$start!==''&&$end<$start)throw new RuntimeException('End date cannot be before start date.');if(!in_array($status,['DRAFT','ACTIVE','CLOSED','ARCHIVED'],true))throw new RuntimeException('Invalid status.');if(!in_array($transport,['BUS','TRAIN','LAUNCH','AIR','OTHER','NONE'],true))throw new RuntimeException('Invalid transport.');$uploadedBanner=upload_tour_image('banner_upload',$id,'cover');$uploadedLogo=upload_tour_image('logo_upload',$id,'logo');if($uploadedBanner!=='')$banner=$uploadedBanner;if($uploadedLogo!=='')$logo=$uploadedLogo;$q=$db->prepare('UPDATE tours SET name=?,start_date=?,end_date=?,default_fee=?,description=?,status=? WHERE id=? AND organization_id=?');$q->execute([$name,$start?:null,$end?:null,$fee,$desc?:null,$status,$id,$orgId]);$s=$db->prepare('INSERT INTO tour_settings(tour_id,setting_key,setting_value,value_type) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),value_type=VALUES(value_type)');$s->execute([$id,'default_transport',$transport,'STRING']);$s->execute([$id,'banner_image',$banner,'STRING']);$s->execute([$id,'logo_image',$logo,'STRING']);$s->execute([$id,'departure_options',json_encode($departures,JSON_UNESCAPED_UNICODE),'JSON']);$q=$db->prepare('INSERT INTO tour_public_pages(tour_id,status,theme_key,title,cover_image,logo_image) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE cover_image=VALUES(cover_image),logo_image=VALUES(logo_image)');$q->execute([$id,'DRAFT','classic',$name,$banner?:null,$logo?:null]);saas_audit('tour.updated','tour',$id,json_encode(['name'=>$name,'status'=>$status],JSON_UNESCAPED_UNICODE));$ok='Tour updated.';$t['name']=$name;$t['start_date']=$start;$t['end_date']=$end;$t['default_fee']=$fee;$t['description']=$desc;$t['status']=$status;$settings['default_transport']=$transport;$settings['banner_image']=$banner;$settings['logo_image']=$logo;$settings['departure_options']=json_encode($departures,JSON_UNESCAPED_UNICODE);}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit tour</title><style>*{box-sizing:border-box}body{font-family:Inter,Arial,sans-serif;background:#f5f7fb;margin:0;color:#172033}.box{max-width:820px;margin:35px auto;background:#fff;padding:28px;border-radius:18px;box-shadow:0 8px 30px #0001}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:block;font-size:13px;font-weight:700;margin:12px 0}input,select,textarea,button{width:100%;padding:11px;border:1px solid #d0d5dd;border-radius:9px;font:inherit}textarea{min-height:100px}button{background:#155eef;color:#fff;border-color:#155eef;font-weight:800;cursor:pointer}.actions{display:flex;gap:10px;margin-top:18px}.actions a{padding:11px 14px;border:1px solid #d0d5dd;border-radius:9px}.msg{padding:11px;border-radius:9px}.ok{background:#ecfdf3;color:#067647}.err{background:#fef3f2;color:#b42318}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><main class="box"><p><a href="tours.php">← Back to tours</a></p><h1>Edit tour</h1><?php if($ok):?><div class="msg ok"><?=saas_h($ok)?></div><?php endif;?><?php if($error):?><div class="msg err"><?=saas_h($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="grid"><label>Tour name<input name="name" value="<?=saas_h($t['name'])?>" required></label><label>Status<select name="status"><?php foreach(['DRAFT','ACTIVE','CLOSED','ARCHIVED'] as $s):?><option <?=$t['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></label><label>Start date<input type="date" name="start_date" value="<?=saas_h($t['start_date']??'')?>"></label><label>End date<input type="date" name="end_date" value="<?=saas_h($t['end_date']??'')?>"></label><label>Default fee<input type="number" step="0.01" min="0" name="default_fee" value="<?=saas_h($t['default_fee'])?>"></label><label>Default transport<select name="default_transport"><?php foreach(['BUS'=>'Bus','TRAIN'=>'Train','LAUNCH'=>'Launch / Ferry','AIR'=>'Air','OTHER'=>'Other','NONE'=>'Not selected'] as $k=>$v):?><option value="<?=$k?>" <?=($settings['default_transport']??'NONE')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Cover image upload<input type="file" name="banner_upload" accept="image/jpeg,image/png,image/webp"><small>Recommended 1600 × 600 px · min 1200 × 450 · max 5 MB</small></label><label>Logo upload<input type="file" name="logo_upload" accept="image/jpeg,image/png,image/webp"><small>Recommended 500 × 150 px · min 200 × 60 · max 5 MB</small></label><label style="grid-column:1/-1">Cover image URL<input name="banner_image" value="<?=saas_h($settings['banner_image']??'')?>" placeholder="https://..."></label><label style="grid-column:1/-1">Logo image URL<input name="logo_image" value="<?=saas_h($settings['logo_image']??'')?>" placeholder="https://..."></label><label style="grid-column:1/-1">Departure options <small>(one per line; shown as passenger dropdown)</small><textarea name="departure_options" rows="5" placeholder="Dhaka&#10;Mirpur 10&#10;Uttara&#10;Farmgate"><?=saas_h(implode("\n",json_decode((string)($settings['departure_options']??'[]'),true)?:[]))?></textarea></label><label style="grid-column:1/-1">Description<textarea name="description"><?=saas_h($t['description']??'')?></textarea></label></div><div class="actions"><button>Save changes</button><a href="tour_open.php?id=<?=$id?>">Open dashboard</a></div></form></main></body></html>